use super::*;
#[test]
fn owned_history_fold_supersessions_receive_original_index_and_retire_native_custody(){
    use semio_framework_value::retained_clone::{RetainedCloneGrant,RetainedCloneProgress};
    let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
    let mut fold=protocol::HistoryFold::default();let mut independent=serde_json::Map::new();let mut pointers=BTreeMap::new();
    for target in law["targets"].as_array().unwrap(){let target=target.as_str().unwrap();let mut payload=Vec::with_capacity(law["extent"].as_u64().unwrap() as usize);payload.resize(law["logicalItems"].as_u64().unwrap() as usize,37u8);pointers.insert(target.to_owned(),payload.as_ptr() as usize);fold.supersessions.insert(MutationId(target.into()),protocol::EffectiveSupersession{transition_id:format!("transition-{target}"),actor:"actor".into(),timestamp:HybridLogicalTimestamp::new(0,0),scope:None,replacement:protocol::InputReplacement::Input{schema:"owned/v1".into(),payload}});independent.insert(target.into(),serde_json::json!({"transition":format!("transition-{target}"),"payload":[37]}));}
    let received:EffectiveSupersessions=fold.supersessions;
    let(actual,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||received.keys().map(|target|target.0.as_str()).eq(law["expectedOrder"].as_array().unwrap().iter().map(|target|target.as_str().unwrap())));assert!(actual);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
    for(target,record)in &received{let protocol::InputReplacement::Input{payload,..}=&record.replacement else{panic!("expected input")};assert_eq!(payload.as_ptr() as usize,pointers[&target.0]);assert_eq!(record.transition_id,independent[&target.0]["transition"].as_str().unwrap());}
    for(target,next)in law["lowerBounds"].as_object().unwrap(){let key=MutationId(target.clone());let(actual,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||received.first_entry_after(&key).map(|(target,_)|target.0.as_str()));assert_eq!(actual,next.as_str());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
    let(mut retirement,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||ArtifactStoreSupersessionRetirement::new(received));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
    for _ in 0..100000{if retirement.terminal_is_empty(){break;}let demand=(retirement.next_capacity_byte_demand(7).unwrap(),retirement.next_release_byte_demand().unwrap(),retirement.next_depth_demand().unwrap());let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:7,maximum_capacity_bytes:demand.0,maximum_release_bytes:demand.1,maximum_depth:demand.2};let mut denied=vec![RetainedCloneGrant{maximum_items:0,..grant}];if demand.0>0{denied.push(RetainedCloneGrant{maximum_capacity_bytes:demand.0-1,..grant});}if demand.1>0{denied.push(RetainedCloneGrant{maximum_release_bytes:demand.1-1,..grant});}if demand.2>0{denied.push(RetainedCloneGrant{maximum_depth:0,..grant});}for grant in denied{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||retirement.close_step(grant));if let Ok(step)=step{assert_eq!(step.progress(),RetainedCloneProgress::default());}assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!((retirement.next_capacity_byte_demand(7).unwrap(),retirement.next_release_byte_demand().unwrap(),retirement.next_depth_demand().unwrap()),demand);}let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||retirement.close_step(grant).unwrap());let progress=step.progress();assert!(progress.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));}
    assert!(retirement.terminal_is_empty());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(retirement));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));println!("[DEBUG] Store receives exact original HistoryFoldIndex; independent JSON ordering and borrowed successor queries agree; payload pointers retained; all arena/key/payload/scaffold releases equal independent grants; terminal drop0heap");
}
